export const records = [{"schema_version":1,"id":"AUT-0561","slug":"customer-referral-purchase-reward-eligibility","title":"Перевірка права на винагороду за рекомендовану покупку","summary":"Виявлену реферальну покупку звіряють з умовами програми, поверненнями та строком перевірки до погодження винагороди.","problem":"Наявність реферальної покупки помилково вважають правом на винагороду. Повернення, підозрілий зв’язок або помилковий автор рекомендації залишаються неперевіреними до видачі.","outcome":"Реферальна покупка має пояснену придатність і перевірене рішення до видачі; виявлення, право й фактична винагорода відокремлені.","category":"marketing","subcategory":"campaign-operations","roles":["marketer","sales-manager"],"industries":["cross-industry"],"triggers":["Отримано реферальну покупку або наближається завершення її строку перевірки."],"workflow_steps":["Зберегти покупку, клієнта, автора рекомендації, програму, редакцію умов і строк перевірки.","Звірити новизну клієнта, допустимі покупки, пороги й ліміти; виявлений зв’язок не прирівнювати до права на винагороду.","Отримати актуальні повернення й скасування за можливостями інтеграції; підозрілу рекомендацію передати на розгляд без твердження про доведене шахрайство.","Погодити конкретне рішення до завершення строку; помилкового автора виправляти дозволеним маршрутом, а не підміною запису чи загальною дискваліфікацією.","Прочитати фактичну придатність і результат винагороди; уже видану винагороду не вважати відкликаною після пізнього виправлення."],"requirements":["Є правила реферальної програми, ключ покупки й автора рекомендації.","Доступні строки перевірки, повернення та фактичний стан винагороди."],"limitations":["Автоматичне виявлення повернень залежить від інтеграції; після строку можливості виправлення обмежені.","Не гарантує відкликання виданої винагороди та не розраховує плату провайдера або податки.","Можливості й права конкретного середовища перевіряють перед впровадженням; години попередні."],"problems":["Наявність реферальної покупки помилково вважають правом на винагороду. Повернення, підозрілий зв’язок або помилковий автор рекомендації залишаються неперевіреними до видачі."],"synonyms":["право на реферальну винагороду","перевірка рекомендованої покупки","строк перевірки рекомендації клієнта"],"search_queries":["як не видати реферальну винагороду за повернену чи непридатну покупку"],"sources":[{"type":"vendor_documentation","url":"https://help.referralcandy.com/en/articles/6643782-troubleshooting-referral-detection","title":"ReferralCandy: Referral detection","checked_at":"2026-10-09","supports":"Detection і reward eligibility різні; є пороги, ліміти й review period. Підозра не є блокуванням; перепризначення автора та відкликання виданої винагороди обмежені."},{"type":"vendor_documentation","url":"https://help.referralcandy.com/en/articles/6657347-deleting-a-purchase-and-disqualifying-a-referral","title":"ReferralCandy: Managing referred purchases","checked_at":"2026-10-09","supports":"Повернення обробляються по-різному залежно від інтеграції. Delete purchase і disqualify referral мають різну область; остання зачіпає пару friend–advocate, не звільняє зв’язок для нового автора."},{"type":"inferred_pattern","title":"Редакційна модель маркетингу та продажів","supports":"Погодження, звірка, винятки, приклад, питання й години — гіпотези для аудиту. Первинні джерела описують власні системи постачальників, а не готову реалізацію PlanFix чи клієнтський кейс CRMCUSTOMS."}],"status":"draft","variants":[{"id":"customer-referral-purchase-reward-eligibility-tracked","title":"Контроль із підтвердженням результату","description":"Виявлену реферальну покупку звіряють з умовами програми, поверненнями та строком перевірки до погодження винагороди.","best_for":["Команда має погоджені правила та перевірені джерела маркетингу й продажів."],"example":"Покупку виявили як реферальну, але до кінця перевірки товар повернули. Команда звірила актуальну суму й рішення до видачі винагороди.","implementation_methods":["Вести окремі стани виявлення, придатності та винагороди.","Перевіряти повернення, підозри й рішення до завершення строку."],"complexity":"medium","hours_min":22,"hours_max":44,"requirements":["Є правила реферальної програми, ключ покупки й автора рекомендації.","Доступні строки перевірки, повернення та фактичний стан винагороди."],"limitations":["Автоматичне виявлення повернень залежить від інтеграції; після строку можливості виправлення обмежені.","Не гарантує відкликання виданої винагороди та не розраховує плату провайдера або податки."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0112","reason":"HR-рекомендація залежить від найму кандидата; тут покупка, повернення, зв’язок покупець–автор та реферальні обмеження."},{"type":"related","target_id":"AUT-0238","reason":"Партнерська реєстрація захищає конкретну угоду й зовнішнє схвалення; тут право на винагороду за покупку клієнта."},{"type":"related","target_id":"AUT-0083","reason":"Активація коду не підтверджує придатність покупки для реферальної винагороди."},{"type":"related","target_id":"AUT-0303","reason":"Видача конкурсного призу виконує рішення щодо переможця, а не визначає придатність реферальної покупки."}],"configurator_questions":[{"id":"customer-referral-purchase-reward-eligibility-returns","question":"Чи потрібно отримувати повернення з іншої системи?","help_text":"Зіставте покупки й зміни в межах строку перевірки.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Зіставте покупки й зміни в межах строку перевірки."}]},{"id":"customer-referral-purchase-reward-eligibility-rules","question":"Чи є накопичувальні пороги або кілька рівнів винагород?","help_text":"Погодьте придатні покупки й ліміти без повторного нарахування.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Погодьте придатні покупки й ліміти без повторного нарахування."}]}]},{"schema_version":1,"id":"AUT-0562","slug":"creator-marketing-partnership-pause-control","title":"Контроль призупинення маркетингової співпраці з автором","summary":"Погоджена пауза співпраці має перевірений результат для авторських посилань, кодів і незатребуваних пропозицій; виплати розглядають окремо.","problem":"Співпрацю вважають призупиненою після повідомлення, але партнерські посилання лишаються активними. Команда припускає, що пауза автоматично скасувала всі виплати й опублікований контент.","outcome":"Стан співпраці й охоплені пропозиції перевірені; невиконані дії та чинні зобов’язання мають окремі рішення.","category":"marketing","subcategory":"campaign-operations","roles":["marketer","sales-manager"],"industries":["cross-industry"],"triggers":["Власник програми погодив призупинення співпраці з конкретним автором."],"workflow_steps":["Зафіксувати автора, програму, підставу, дату й охоплені посилання, коди та пропозиції.","Відокремити незатребувані подарунки, видані переваги, очікувані виплати й уже опубліковані матеріали.","Застосувати погоджену паузу в джерелі та прочитати стан співпраці, посилань і кодів; повідомлення не вважати результатом.","Передати виплати та чинні матеріали на окремий розгляд; паузу не використовувати як автоматичне скасування договору чи прав.","Зберегти перевірений результат і винятки; відновлення погоджувати з актуальною програмою та повторною звіркою пропозицій."],"requirements":["Є реєстр авторів, програм і активних партнерських пропозицій.","Визначено власника рішення, область паузи й маршрут окремих зобов’язань."],"limitations":["Пауза не прибирає автоматично публікації й не відкликає видані винагороди.","Виплати, договірні умови та доступність відновлення перевіряються окремо.","Можливості й права конкретного середовища перевіряють перед впровадженням; години попередні."],"problems":["Співпрацю вважають призупиненою після повідомлення, але партнерські посилання лишаються активними. Команда припускає, що пауза автоматично скасувала всі виплати й опублікований контент."],"synonyms":["пауза партнерства з автором","деактивація авторських пропозицій","призупинення influencer співпраці"],"search_queries":["як призупинити співпрацю з блогером і перевірити його активні посилання та промокоди"],"sources":[{"type":"vendor_documentation","url":"https://help.shopify.com/en/manual/promoting-marketing/collabs/merchants/creator-connections","title":"Shopify Collabs: Creator connections","checked_at":"2026-10-09","supports":"Pause деактивує links/codes і скасовує незатребувані gifts. Pending payouts розглядаються окремо. Reactivate передбачає вибір Program; зберігається історія inactive connection."},{"type":"inferred_pattern","title":"Редакційна модель маркетингу та продажів","supports":"Погодження, звірка, винятки, приклад, питання й години — гіпотези для аудиту. Первинні джерела описують власні системи постачальників, а не готову реалізацію PlanFix чи клієнтський кейс CRMCUSTOMS."}],"status":"draft","variants":[{"id":"creator-marketing-partnership-pause-control-tracked","title":"Контроль із підтвердженням результату","description":"Погоджена пауза співпраці має перевірений результат для авторських посилань, кодів і незатребуваних пропозицій; виплати розглядають окремо.","best_for":["Команда має погоджені правила та перевірені джерела маркетингу й продажів."],"example":"Після погодженої паузи команда перевірила коди й посилання автора. Очікувану виплату передала на окреме рішення замість припущення про її скасування.","implementation_methods":["Вести рішення паузи з областю активних пропозицій.","Звіряти фактичні стани й окремі зобов’язання перед закриттям."],"complexity":"medium","hours_min":18,"hours_max":36,"requirements":["Є реєстр авторів, програм і активних партнерських пропозицій.","Визначено власника рішення, область паузи й маршрут окремих зобов’язань."],"limitations":["Пауза не прибирає автоматично публікації й не відкликає видані винагороди.","Виплати, договірні умови та доступність відновлення перевіряються окремо."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0079","reason":"Завершення роботи працівника припиняє доступи й передає відповідальність. Тут стан зовнішньої маркетингової співпраці та авторські пропозиції."},{"type":"related","target_id":"AUT-0255","reason":"Дозволи стосуються використання матеріалу; пауза партнерства не є автоматичним відкликанням дозволу."},{"type":"related","target_id":"AUT-0337","reason":"Маркування перевіряє конкретну публікацію, не активність партнерських пропозицій автора."},{"type":"related","target_id":"AUT-0238","reason":"Реєстрація однієї партнерської угоди не управляє загальним станом співпраці з автором."}],"configurator_questions":[{"id":"creator-marketing-partnership-pause-control-programs","question":"Чи має автор кілька програм або магазинів?","help_text":"Визначте область паузи й незалежні пропозиції.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Визначте область паузи й незалежні пропозиції."}]},{"id":"creator-marketing-partnership-pause-control-commitments","question":"Чи є незавершені подарунки, виплати або матеріали?","help_text":"Передайте кожне зобов’язання на окреме підтверджене рішення.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Передайте кожне зобов’язання на окреме підтверджене рішення."}]}]},{"schema_version":1,"id":"AUT-0563","slug":"sales-draft-order-checkout-completion-control","title":"Контроль оформлення погодженої чернетки замовлення","summary":"Клієнт отримує придатний маршрут оформлення підготовленого продавцем замовлення; завершення звіряють із фактичним створеним замовленням.","problem":"Продавець надсилає посилання, за яким клієнт не може завершити покупку через залишок чи змінені умови. Надісланий рахунок помилково вважають оплаченим замовленням.","outcome":"Чернетка має перевірені умови й маршрут оформлення; фактичне завершення або відкрита перешкода пов’язані з її редакцією.","category":"sales-crm","subcategory":"sales-operations","roles":["sales-manager","sales-representative"],"industries":["cross-industry"],"triggers":["Продавець підготував замовлення поза звичайним кошиком і погодив його передавання клієнту для оформлення."],"workflow_steps":["Зберегти чернетку, клієнта, контакт, редакцію складу, цін і доставки; визначити механізм фіксації цін.","Перевірити придатний залишок і фактичний резерв, якщо він потрібен; створення чернетки саме по собі не вважати резервом.","Звірити правила оформлення й підготувати дозволене посилання; обхід валідацій не вмикати як спосіб приховати перешкоду.","Передати клієнту погоджений маршрут і зберегти результат; не встановлювати Paid до підтвердженого платежу.","Отримати фактичне завершене замовлення й його зв’язок із чернеткою; зміну товарів чи доставки повернути на перегляд, а повтор повідомлення не створює нове замовлення."],"requirements":["Є ключ чернетки, погоджені умови й контакт клієнта.","Доступні джерело товарних залишків, механізм оформлення та фактичний результат."],"limitations":["Посилання не підтверджує оплату, резерв або відвантаження.","Наявність, фіксація цін і доставка залежать від системи; після зміни складу автоматичний перерахунок не припускається.","Можливості й права конкретного середовища перевіряють перед впровадженням; години попередні."],"problems":["Продавець надсилає посилання, за яким клієнт не може завершити покупку через залишок чи змінені умови. Надісланий рахунок помилково вважають оплаченим замовленням."],"synonyms":["чернетка замовлення для клієнта","посилання оформлення draft order","завершення замовлення продавця"],"search_queries":["як дати клієнту оформити підготовлене менеджером замовлення без неактуальних цін і залишків"],"sources":[{"type":"vendor_documentation","url":"https://help.shopify.com/en/manual/fulfillment/managing-orders/create-orders/send-draft","title":"Shopify: Sending invoices for draft orders","checked_at":"2026-10-09","supports":"Invoice/direct link веде до checkout; завершення створює order. Передчасне Paid ламає посилання, нестача запасу блокує оформлення. Price lock і додавання товару впливають на умови; доставка не завжди перераховується."},{"type":"inferred_pattern","title":"Редакційна модель маркетингу та продажів","supports":"Погодження, звірка, винятки, приклад, питання й години — гіпотези для аудиту. Первинні джерела описують власні системи постачальників, а не готову реалізацію PlanFix чи клієнтський кейс CRMCUSTOMS."}],"status":"draft","variants":[{"id":"sales-draft-order-checkout-completion-control-tracked","title":"Контроль із підтвердженням результату","description":"Клієнт отримує придатний маршрут оформлення підготовленого продавцем замовлення; завершення звіряють із фактичним створеним замовленням.","best_for":["Команда має погоджені правила та перевірені джерела маркетингу й продажів."],"example":"Менеджер підготував замовлення телефоном. До надсилання команда перевірила запас і ціну, потім звірила створене клієнтом замовлення з чернеткою.","implementation_methods":["Перевіряти редакцію й придатність оформлення чернетки до передавання.","Зіставляти фактичне завершення та зміни умов із вихідною чернеткою."],"complexity":"medium","hours_min":22,"hours_max":44,"requirements":["Є ключ чернетки, погоджені умови й контакт клієнта.","Доступні джерело товарних залишків, механізм оформлення та фактичний результат."],"limitations":["Посилання не підтверджує оплату, резерв або відвантаження.","Наявність, фіксація цін і доставка залежать від системи; після зміни складу автоматичний перерахунок не припускається."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0010","reason":"Нагадування відстежує паузу після пропозиції; тут придатність checkout і перехід чернетки в оформлене замовлення."},{"type":"related","target_id":"AUT-0373","reason":"Передоплата дозволяє відвантаження вже наявного замовлення; тут створення замовлення через клієнтське оформлення чернетки."},{"type":"related","target_id":"AUT-0195","reason":"Звірка магазину відновлює пропущені CRM-записи; тут підготовлена продавцем чернетка та її завершення клієнтом."},{"type":"related","target_id":"AUT-0515","reason":"Редакція пропозиції під час переговорів не підтверджує придатність checkout, залишку та створення замовлення."}],"configurator_questions":[{"id":"sales-draft-order-checkout-completion-control-inventory","question":"Чи потрібно звіряти резерв із зовнішнім складом?","help_text":"Погодьте ключі товарів і підтверджений стан резерву.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Погодьте ключі товарів і підтверджений стан резерву."}]},{"id":"sales-draft-order-checkout-completion-control-changes","question":"Чи може змінюватися склад або доставка після надсилання?","help_text":"Визначте повторне погодження й перевірку актуального маршруту.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Визначте повторне погодження й перевірку актуального маршруту."}]}]},{"schema_version":1,"id":"AUT-0564","slug":"marketing-cohort-retention-period-review","title":"Перегляд утримання когорт залучених користувачів","summary":"Групи з однаковим моментом залучення порівнюють за поверненням у зіставних наступних періодах, без змішування різного віку груп.","problem":"Нова група має менше часу для повторної дії, але її вважають гіршою за стару. Повернення в окремому періоді змішують із накопичувальним або безперервним утриманням.","outcome":"Когорти мають відтворювані умови входу, повернення та розрахунку; рішення про утримання спирається на зіставний вік і повноту даних.","category":"marketing","subcategory":"attribution","roles":["marketer","sales-manager"],"industries":["cross-industry"],"triggers":["Настав строк перегляду утримання після залучення нової групи користувачів."],"workflow_steps":["Зберегти правило входу до когорти, подію повернення, одиницю періоду, часовий пояс і джерело ідентифікації.","Звірити повноту потрібних подій і межі охоплення; ідентичність пристрою не прирівнювати до єдиного клієнта CRM.","Обчислити стандартний, безперервний або накопичувальний результат за погодженим визначенням; один підсумок не підміняти іншим.","Порівняти когорти на однаковому віці та завершених періодах; невидимі чи порогово приховані дані не трактувати як нуль.","Маркетолог погоджує гіпотезу покращення й наступний зріз; відмінність груп не називати доказом причинного впливу кампанії."],"requirements":["Є погоджені події входу й повернення та доступне джерело даних.","Визначено календарні періоди, метод розрахунку й мінімальну повноту для порівняння."],"limitations":["GA4 cohort exploration використовує device data без User-ID; це не повний облік людей чи покупців CRM.","Малі групи, неповні періоди та обмеження джерела можуть робити висновок непридатним.","Можливості й права конкретного середовища перевіряють перед впровадженням; години попередні."],"problems":["Нова група має менше часу для повторної дії, але її вважають гіршою за стару. Повернення в окремому періоді змішують із накопичувальним або безперервним утриманням."],"synonyms":["когортне утримання користувачів","повернення груп залучення","cohort retention за періодами"],"search_queries":["як порівняти повернення нових користувачів різних місяців на однаковому віці групи"],"sources":[{"type":"vendor_documentation","url":"https://support.google.com/analytics/answer/9670133?hl=en","title":"Google Analytics: Cohort exploration","checked_at":"2026-10-09","supports":"Описано inclusion/return criteria, календарну гранулярність та Standard/Rolling/Cumulative. Користувач може належати кільком когортам; device data не враховує User-ID, діють обмеження й thresholding."},{"type":"inferred_pattern","title":"Редакційна модель маркетингу та продажів","supports":"Погодження, звірка, винятки, приклад, питання й години — гіпотези для аудиту. Первинні джерела описують власні системи постачальників, а не готову реалізацію PlanFix чи клієнтський кейс CRMCUSTOMS."}],"status":"draft","variants":[{"id":"marketing-cohort-retention-period-review-tracked","title":"Контроль із підтвердженням результату","description":"Групи з однаковим моментом залучення порівнюють за поверненням у зіставних наступних періодах, без змішування різного віку груп.","best_for":["Команда має погоджені правила та перевірені джерела маркетингу й продажів."],"example":"Липневу й серпневу групи порівняли на другому завершеному місяці після залучення. Серпневий незавершений третій місяць не оголосили нульовим утриманням.","implementation_methods":["Вести конфігурацію когорти й умов повернення з історією.","Порівнювати завершені періоди однакового віку та погоджувати дії з межами даних."],"complexity":"medium","hours_min":20,"hours_max":40,"requirements":["Є погоджені події входу й повернення та доступне джерело даних.","Визначено календарні періоди, метод розрахунку й мінімальну повноту для порівняння."],"limitations":["GA4 cohort exploration використовує device data без User-ID; це не повний облік людей чи покупців CRM.","Малі групи, неповні періоди та обмеження джерела можуть робити висновок непридатним."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0542","reason":"RFM класифікує клієнтів за давністю, частотою й сумою на зрізі; когорти порівнюють повернення груп на однаковому віці."},{"type":"related","target_id":"AUT-0151","reason":"Повернення клієнта до контакту відкриває індивідуальний цикл після паузи, а не аналіз утримання груп."},{"type":"related","target_id":"AUT-0525","reason":"Атрибуція розподіляє внесок каналів, не рахує повернення когорти в наступних періодах."}],"configurator_questions":[{"id":"marketing-cohort-retention-period-review-events","question":"Чи потрібно підготувати або звірити події повернення?","help_text":"Погодьте значення подій і повноту джерела до розрахунку.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Погодьте значення подій і повноту джерела до розрахунку."}]},{"id":"marketing-cohort-retention-period-review-sources","question":"Чи потрібно порівнювати когорти з кількох систем?","help_text":"Узгодьте ідентифікацію, календарі й методику без змішування людей та пристроїв.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Узгодьте ідентифікацію, календарі й методику без змішування людей та пристроїв."}]}]},{"schema_version":1,"id":"AUT-0565","slug":"marketing-seasonal-search-demand-planning-review","title":"Перегляд сезонного пошукового попиту для плану кампаній","summary":"Порівнювані часові ряди пошукового інтересу допомагають погодити підготовку кампанії; відносний індекс не видають за кількість покупців.","problem":"Команда планує кампанію після сезонного піку або трактує індекс 100 як обсяг продажів. Ряди з різними областями й шкалами порівнюють як абсолютні значення.","outcome":"Сезонні гіпотези мають збережені параметри й перевірені межі; погоджені строки підготовки спираються також на фактичні бізнес-дані.","category":"marketing","subcategory":"campaign-operations","roles":["marketer","sales-manager"],"industries":["cross-industry"],"triggers":["Підготовлено план кампаній на новий сезон або суттєво змінився пошуковий інтерес до теми."],"workflow_steps":["Зберегти теми або запити, географію, часовий діапазон, тип пошуку та дату зрізу.","Отримати порівнювані ряди й перевірити спільну область та нормалізацію; окремо масштабовані індекси не складати як обсяги.","Відокремити повторювану сезонність від разового сплеску й малих даних; нуль низькочастотної теми не називати відсутністю попиту.","Зіставити гіпотезу з доступними зверненнями чи продажами; маркетолог погоджує строк підготовки й підстави без автоматичної зміни бюджету.","Зберегти рішення й наступну перевірку; оновлення вибірки або параметрів пояснити перед порівнянням із попереднім зрізом."],"requirements":["Є перелік тем, погоджена область порівняння й доступний часовий ряд.","Визначено власника плану та додаткове бізнес-джерело для перевірки гіпотез."],"limitations":["Google Trends є вибіркою нормалізованого інтересу, не абсолютним обсягом, опитуванням чи прогнозом продажів.","Доступність автоматичного отримання перевіряють окремо; допускається погоджений імпорт, без припущення загальнодоступного API.","Можливості й права конкретного середовища перевіряють перед впровадженням; години попередні."],"problems":["Команда планує кампанію після сезонного піку або трактує індекс 100 як обсяг продажів. Ряди з різними областями й шкалами порівнюють як абсолютні значення."],"synonyms":["сезонність пошукового інтересу","план кампанії за трендами","відносний індекс попиту"],"search_queries":["як спланувати кампанію до сезонного піку попиту і правильно порівняти пошукові тренди"],"sources":[{"type":"vendor_documentation","url":"https://support.google.com/trends/answer/4365533?hl=en","title":"Google Trends: Data FAQ","checked_at":"2026-10-09","supports":"Trends дає вибірку запитів, нормалізацію за часом/географією й шкалу 0–100. Однаковий індекс не означає однаковий обсяг; низький обсяг може бути 0. Сплеск не доводить загальної популярності."},{"type":"inferred_pattern","title":"Редакційна модель маркетингу та продажів","supports":"Погодження, звірка, винятки, приклад, питання й години — гіпотези для аудиту. Первинні джерела описують власні системи постачальників, а не готову реалізацію PlanFix чи клієнтський кейс CRMCUSTOMS."}],"status":"draft","variants":[{"id":"marketing-seasonal-search-demand-planning-review-tracked","title":"Контроль із підтвердженням результату","description":"Порівнювані часові ряди пошукового інтересу допомагають погодити підготовку кампанії; відносний індекс не видають за кількість покупців.","best_for":["Команда має погоджені правила та перевірені джерела маркетингу й продажів."],"example":"Повторюваний весняний пік теми звірили з фактичними зверненнями. Команда погодила підготовку раніше, не переводячи індекс Trends у кількість продажів.","implementation_methods":["Вести зіставні часові ряди й параметри пошукового інтересу.","Погоджувати сезонну гіпотезу та строки підготовки за кількома джерелами."],"complexity":"medium","hours_min":18,"hours_max":36,"requirements":["Є перелік тем, погоджена область порівняння й доступний часовий ряд.","Визначено власника плану та додаткове бізнес-джерело для перевірки гіпотез."],"limitations":["Google Trends є вибіркою нормалізованого інтересу, не абсолютним обсягом, опитуванням чи прогнозом продажів.","Доступність автоматичного отримання перевіряють окремо; допускається погоджений імпорт, без припущення загальнодоступного API."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0518","reason":"Темп бюджету використовує план і поточні витрати; тут сезонна гіпотеза із зовнішнього пошукового інтересу до запуску."},{"type":"related","target_id":"AUT-0103","reason":"Контент-план контролює виготовлення та публікацію матеріалів; тут аналіз визначає строки підготовки кампанії."},{"type":"related","target_id":"AUT-0520","reason":"Конкуренція сторінок розглядає видимість URL у пошуку, не зовнішню сезонність теми."}],"configurator_questions":[{"id":"marketing-seasonal-search-demand-planning-review-topics","question":"Чи потрібно порівнювати багато тем або регіонів?","help_text":"Погодьте спільні параметри й масштаби порівняння.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Погодьте спільні параметри й масштаби порівняння."}]},{"id":"marketing-seasonal-search-demand-planning-review-business","question":"Чи потрібно отримувати бізнес-дані для перевірки сезонності?","help_text":"Зіставте періоди й область звернень або продажів без твердження про причинність.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Зіставте періоди й область звернень або продажів без твердження про причинність."}]}]},{"schema_version":1,"id":"AUT-0566","slug":"marketing-qualified-lead-sales-acceptance","title":"Контроль приймання маркетингового ліда продавцем","summary":"Лід із погодженою маркетинговою готовністю передають разом із підставою; продавець підтверджує приймання або пояснену потребу в уточненні.","problem":"Маркетинг позначив лід готовим, але продавець не отримав контексту або не прийняв його в роботу. Падіння оцінки помилково вважають автоматичним скасуванням попередньої кваліфікації.","outcome":"Передавання має збережені критерії, контекст і підтверджене рішення продавця; готовність не підміняє нову угоду або просто місце в черзі.","category":"marketing","subcategory":"campaign-operations","roles":["marketer","sales-manager"],"industries":["cross-industry"],"triggers":["Відкритий лід виконав чинні погоджені критерії маркетингової готовності."],"workflow_steps":["Зберегти ключ ліда, редакцію критеріїв, чинні моделі й підстави готовності; закриті чи вже перетворені ліди відокремити.","Звірити потрібні відомості й допустимий контекст взаємодій; бал не вважати доказом наміру купити.","Передати продавцю один пакет із підставою та строком рішення; саме призначення не вважати прийманням.","Отримати підтвердження роботи або причину уточнення; зберегти рішення й відповідального без автоматичного створення нової угоди.","Переглянути непідтверджені передавання та змінені підстави; зменшення бала не скасовує готовність або приймання без погодженого правила."],"requirements":["Маркетинг і продажі погодили критерії готовності та зміст передавання.","Є ключ ліда, актуальний стан і спосіб зберегти приймання продавцем."],"limitations":["Кваліфікація не підтверджує купівлю й не створює згоди на контакт.","Статуси та автоматичне зняття готовності залежать від системи; приймання продавцем є проєктною моделлю.","Можливості й права конкретного середовища перевіряють перед впровадженням; години попередні."],"problems":["Маркетинг позначив лід готовим, але продавець не отримав контексту або не прийняв його в роботу. Падіння оцінки помилково вважають автоматичним скасуванням попередньої кваліфікації."],"synonyms":["приймання маркетингового ліда","передавання sales ready","маркетингова готовність і рішення продавця"],"search_queries":["як передавати прогріті ліди з маркетингу і бачити що продавець прийняв їх у роботу"],"sources":[{"type":"vendor_documentation","url":"https://learn.microsoft.com/en-us/dynamics365/customer-insights/journeys/real-time-marketing-qualify-leads","title":"Microsoft: Qualify the best leads","checked_at":"2026-10-09","supports":"Критерії live scoring models оновлюють Marketing Qualified/Sales-Ready у відкритих лідів і можуть запускати призначення. Падіння оцінки саме не знімає Marketing Qualified. Приймання й строк — проєктний контроль."},{"type":"inferred_pattern","title":"Редакційна модель міжкомандного та інформаційного контролю","supports":"Погодження, звірка, винятки, приклад, питання й години — гіпотези для аудиту. Первинні джерела описують власні системи постачальників, а не готову реалізацію PlanFix чи клієнтський кейс CRMCUSTOMS."}],"status":"draft","variants":[{"id":"marketing-qualified-lead-sales-acceptance-tracked","title":"Контроль із підтвердженням результату","description":"Лід із погодженою маркетинговою готовністю передають разом із підставою; продавець підтверджує приймання або пояснену потребу в уточненні.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Маркетинг передав лід із підставою готовності. Продавець попросив уточнити потребу; цей результат зберегли замість звіту про прийняту угоду.","implementation_methods":["Вести готовність і пакет передавання за погодженими критеріями.","Отримувати окреме рішення продавця й контролювати невирішені передавання."],"complexity":"medium","hours_min":20,"hours_max":40,"requirements":["Маркетинг і продажі погодили критерії готовності та зміст передавання.","Є ключ ліда, актуальний стан і спосіб зберегти приймання продавцем."],"limitations":["Кваліфікація не підтверджує купівлю й не створює згоди на контакт.","Статуси та автоматичне зняття готовності залежать від системи; приймання продавцем є проєктною моделлю."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0513","reason":"Пріоритет за ймовірністю ранжує чергу; тут міжкомандне передавання та рішення продавця щодо готового ліда."},{"type":"related","target_id":"AUT-0516","reason":"Перетворення кваліфікованого ліда створює або пов’язує угоду; приймання передавання саме цього не робить."},{"type":"related","target_id":"AUT-0001","reason":"Розподіл визначає відповідального; він не підтверджує отримання контексту й приймання маркетингового ліда."},{"type":"related","target_id":"AUT-0015","reason":"Передавання після продажу запускає сервіс; тут маркетинг передає лід до роботи продавця."}],"configurator_questions":[{"id":"marketing-qualified-lead-sales-acceptance-models","question":"Чи потрібно поєднати кілька моделей або критеріїв готовності?","help_text":"Погодьте логіку, редакції та актуальні джерела оцінок.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Погодьте логіку, редакції та актуальні джерела оцінок."}]},{"id":"marketing-qualified-lead-sales-acceptance-teams","question":"Чи працюють маркетинг і продажі в різних системах?","help_text":"Зіставте ключ ліда, пакет і підтверджене рішення без подвійного передавання.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Зіставте ключ ліда, пакет і підтверджене рішення без подвійного передавання."}]}]},{"schema_version":1,"id":"AUT-0567","slug":"sales-multiparticipant-meeting-time-consensus","title":"Узгодження часу зустрічі з кількома учасниками","summary":"Запропоновані часові варіанти й відповіді обов’язкових учасників приводять до однієї перевіреної календарної зустрічі.","problem":"Менеджер збирає відповіді в листуванні, але бронює час без ключового учасника. Тимчасові резерви лишаються після вибору, а повторна відповідь створює друге запрошення.","outcome":"Зустріч має погоджений час, склад учасників і календарний ID; тимчасові варіанти та невирішені відповіді оброблені явно.","category":"sales-crm","subcategory":"sales-operations","roles":["sales-manager","sales-representative"],"industries":["cross-industry"],"triggers":["Для переговорів потрібно погодити один час із кількома учасниками."],"workflow_steps":["Зберегти зустріч, тривалість, часові пояси й обов’язкових та необов’язкових учасників.","Підготувати придатні варіанти; доступність зовнішнього календаря не припускати, якщо її немає.","Отримати відповіді й перевірити погоджений критерій згоди; більшість голосів не підміняє згоду всіх потрібних учасників.","Перед остаточним вибором звірити склад і актуальні конфлікти; неоднозначні варіанти передати організатору.","Прочитати створену календарну подію, час і учасників; зняти тимчасові резерви дозволеним механізмом та закрити опитування без повторного створення."],"requirements":["Є організатор, перелік учасників і погоджений критерій вибору часу.","Доступні механізм голосування, календар і підтвердження фактичної події."],"limitations":["Голосування не гарантує присутності на зустрічі; зовнішня доступність може бути невідомою.","Автопланування, автентифікація учасників і календарні резерви залежать від середовища.","Можливості й права конкретного середовища перевіряють перед впровадженням; години попередні."],"problems":["Менеджер збирає відповіді в листуванні, але бронює час без ключового учасника. Тимчасові резерви лишаються після вибору, а повторна відповідь створює друге запрошення."],"synonyms":["опитування часу зустрічі","спільний слот переговорів","згода обов’язкових учасників"],"search_queries":["як узгодити час переговорів з кількома учасниками і не створити зайві зустрічі"],"sources":[{"type":"vendor_documentation","url":"https://support.microsoft.com/en-us/outlook/auto-scheduling-in-scheduling-poll-for-new-outlook","title":"Microsoft Outlook: Scheduling Poll auto scheduling","checked_at":"2026-10-09","supports":"Згода визначається за required attendees; optional враховуються при кількох придатних варіантах. Можливе ручне планування до згоди; календарні holds знімаються після остаточного планування."},{"type":"vendor_documentation","url":"https://support.microsoft.com/en-us/outlook/find-the-best-meeting-time-for-everyone-with-outlook-scheduling-poll","title":"Microsoft Outlook: Scheduling Poll","checked_at":"2026-10-09","supports":"Організатору потрібна Exchange Online mailbox; зовнішні учасники можуть голосувати за посиланням. Наявність календарної доступності залежить від учасника."},{"type":"inferred_pattern","title":"Редакційна модель міжкомандного та інформаційного контролю","supports":"Погодження, звірка, винятки, приклад, питання й години — гіпотези для аудиту. Первинні джерела описують власні системи постачальників, а не готову реалізацію PlanFix чи клієнтський кейс CRMCUSTOMS."}],"status":"draft","variants":[{"id":"sales-multiparticipant-meeting-time-consensus-tracked","title":"Контроль із підтвердженням результату","description":"Запропоновані часові варіанти й відповіді обов’язкових учасників приводять до однієї перевіреної календарної зустрічі.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Троє потрібних учасників погодили другий варіант. Організатор перевірив фактичну подію й зняття інших резервів; четвертого необов’язкового учасника залишив у запрошенні.","implementation_methods":["Вести варіанти часу та відповіді потрібних учасників.","Звіряти один остаточний календарний результат і звільнення тимчасових варіантів."],"complexity":"medium","hours_min":18,"hours_max":36,"requirements":["Є організатор, перелік учасників і погоджений критерій вибору часу.","Доступні механізм голосування, календар і підтвердження фактичної події."],"limitations":["Голосування не гарантує присутності на зустрічі; зовнішня доступність може бути невідомою.","Автопланування, автентифікація учасників і календарні резерви залежать від середовища."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0009","reason":"Підсумок зустрічі починається після її проведення; тут збір згоди на час і створення події."},{"type":"related","target_id":"AUT-0040","reason":"Навантаження команди порівнює планові інтервали; тут голоси зовнішніх учасників і погоджена одна зустріч."},{"type":"related","target_id":"AUT-0288","reason":"Повторний запис відновлює запис після неявки; тут початкове узгодження групового часу."},{"type":"related","target_id":"AUT-0141","reason":"Черга очікування розподіляє вільні квитки, а не узгоджує час між потрібними учасниками."}],"configurator_questions":[{"id":"sales-multiparticipant-meeting-time-consensus-calendars","question":"Чи потрібно звіряти кілька календарних систем?","help_text":"Визначте доступність зовнішніх календарів і підтвердження створеної події.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Визначте доступність зовнішніх календарів і підтвердження створеної події."}]},{"id":"sales-multiparticipant-meeting-time-consensus-changes","question":"Чи може змінюватися склад учасників після початку голосування?","help_text":"Погодьте повторну перевірку згоди та сповіщення про зміну.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Погодьте повторну перевірку згоди та сповіщення про зміну."}]}]},{"schema_version":1,"id":"AUT-0568","slug":"closed-sales-opportunity-reopen-review","title":"Погодження повторного відкриття закритої угоди","summary":"Поновлений інтерес клієнта звіряють із закритою угодою та її наслідками; дозволене відкриття зберігає підставу й попередній результат.","problem":"Менеджер відкриває закриту угоду без перевірки вже створених замовлень або паралельного продажу. Повторне закриття дублює дії, а історія першого результату губиться.","outcome":"Повторно відкрита угода має погоджену підставу, перевірений стан і окремі рішення щодо наслідків; старий продаж не скасований лише зміною стадії.","category":"sales-crm","subcategory":"pipeline","roles":["sales-manager","sales-representative"],"industries":["cross-industry"],"triggers":["Клієнт поновив інтерес до раніше закритої угоди або виявлено потребу виправити її закриття."],"workflow_steps":["Зафіксувати угоду, попереднє закриття, причину повернення й пов’язані замовлення та виконані дії.","Перевірити чи це та сама потреба, чи окремий новий продаж; знайти паралельну активну роботу без автоматичного злиття.","Керівник погоджує відкриття або інший маршрут і рішення щодо вже виконаних наслідків; вони не скасовуються зміною стадії.","Застосувати дозволене відкриття й прочитати фактичний стан, відповідального та план наступної дії.","Зберегти попереднє закриття й нову підставу; для подальшого результату перевірити одноразовість зовнішніх дій та відображення у прогнозі."],"requirements":["Є ключ угоди, історія закриття та реєстр пов’язаних дій.","Визначено право відкриття й правила відокремлення нового продажу від поновлення."],"limitations":["Відкриття угоди не анулює замовлення, договір чи оплату.","Збереження історії й повторні зовнішні дії потребують окремого проєктного контролю.","Можливості й права конкретного середовища перевіряють перед впровадженням; години попередні."],"problems":["Менеджер відкриває закриту угоду без перевірки вже створених замовлень або паралельного продажу. Повторне закриття дублює дії, а історія першого результату губиться."],"synonyms":["повторне відкриття угоди","reopen closed opportunity","поновлення закритого продажу"],"search_queries":["як повернути закриту угоду в роботу не загубивши історію і не створивши дубль продажу"],"sources":[{"type":"vendor_documentation","url":"https://learn.microsoft.com/en-us/dynamics365/sales/close-opportunity-won-lost-sales","title":"Dynamics 365 Sales: Close and reopen opportunities","checked_at":"2026-10-09","supports":"Є дія Reopen Opportunity для закритої угоди при поновленому інтересі. Описано історію Opportunity Close і зміну forecast category при закритті. Контроль наслідків та одноразовості — проєктна модель."},{"type":"inferred_pattern","title":"Редакційна модель міжкомандного та інформаційного контролю","supports":"Погодження, звірка, винятки, приклад, питання й години — гіпотези для аудиту. Первинні джерела описують власні системи постачальників, а не готову реалізацію PlanFix чи клієнтський кейс CRMCUSTOMS."}],"status":"draft","variants":[{"id":"closed-sales-opportunity-reopen-review-tracked","title":"Контроль із підтвердженням результату","description":"Поновлений інтерес клієнта звіряють із закритою угодою та її наслідками; дозволене відкриття зберігає підставу й попередній результат.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Клієнт повернувся до закритої пропозиції. Керівник перевірив відсутність іншого продажу, погодив відкриття й зберіг перше рішення без повторного створення замовлення.","implementation_methods":["Погоджувати підставу й наслідки відкриття конкретної закритої угоди.","Звіряти новий стан та історію без сліпого повтору дій закриття."],"complexity":"medium","hours_min":20,"hours_max":40,"requirements":["Є ключ угоди, історія закриття та реєстр пов’язаних дій.","Визначено право відкриття й правила відокремлення нового продажу від поновлення."],"limitations":["Відкриття угоди не анулює замовлення, договір чи оплату.","Збереження історії й повторні зовнішні дії потребують окремого проєктного контролю."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0522","reason":"Відкладений лід ще не є закритою угодою з результатом і виконаними наслідками."},{"type":"related","target_id":"AUT-0012","reason":"Перевірка умов переходу не визначає рішення щодо поновлення вже закритого продажу та зовнішніх наслідків."},{"type":"related","target_id":"AUT-0011","reason":"Причина втрати пояснює закриття, але не погоджує й не перевіряє повторне відкриття."},{"type":"related","target_id":"AUT-0233","reason":"Коригування прогнозу змінює очікування, не стан закритої угоди."}],"configurator_questions":[{"id":"closed-sales-opportunity-reopen-review-downstream","question":"Чи створило перше закриття документи або замовлення в інших системах?","help_text":"Зіставте виконані дії й окремі рішення без автоматичного скасування.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Зіставте виконані дії й окремі рішення без автоматичного скасування."}]},{"id":"closed-sales-opportunity-reopen-review-history","question":"Чи потрібно зберігати кілька циклів закриття в звітах?","help_text":"Погодьте облік результатів і прогнозу без подвійного рахунку продажу.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Погодьте облік результатів і прогнозу без подвійного рахунку продажу."}]}]},{"schema_version":1,"id":"AUT-0569","slug":"knowledge-search-index-source-change-reconciliation","title":"Звірка пошукової бази знань після зміни джерел","summary":"Змінені й вилучені джерела звіряють із фактично доступними пошуковими документами, щоб база не повертала застарілий зміст.","problem":"Інструкцію змінили або вилучили зі сховища, але пошукова база продовжує повертати старі фрагменти. Успішний запуск індексатора помилково вважають повною звіркою видалень.","outcome":"Кожне охоплене джерело має перевірений пошуковий результат актуальної редакції або підтверджене вилучення; невирішені розбіжності видимі власнику знань.","category":"ai-knowledge-work","subcategory":"knowledge-retrieval","roles":["operations-manager","support-agent"],"industries":["cross-industry"],"triggers":["Оновлено або вилучено джерело знань чи завершився запуск його індексування."],"workflow_steps":["Зберегти стабільні ключі джерел, редакції, пов’язані фрагменти й погоджену область індексування.","Перевірити механізм виявлення змін і видалень; фізичне зникнення файла не вважати автоматичним вилученням пошукового запису.","Запустити дозволене оновлення або вилучення та зберегти ID; видалення джерела виконувати за чинним окремим правилом.","Звірити фактичні редакції та відсутність вилучених записів за ключами й контрольними запитами; статус успіху запуску не закриває розбіжність.","Передати сирітські фрагменти й пропущені зміни власнику; перебудову погодити окремо, а готовність позначити лише для перевіреної області."],"requirements":["Є ключі джерел і фрагментів, редакції та доступний механізм оновлення індексу.","Визначено політику видалення, область й спосіб читання фактичного пошукового результату."],"limitations":["Не підтверджує правильність відповіді ШІ чи права доступу лише за успіхом індексування.","Виявлення видалень має окремі вимоги; пізнє додавання політики не гарантує очищення всіх старих сирітських записів.","Можливості й права конкретного середовища перевіряють перед впровадженням; години попередні."],"problems":["Інструкцію змінили або вилучили зі сховища, але пошукова база продовжує повертати старі фрагменти. Успішний запуск індексатора помилково вважають повною звіркою видалень."],"synonyms":["актуальність пошукового індексу знань","сирітські фрагменти джерела","звірка вилучених документів RAG"],"search_queries":["як прибрати старі фрагменти з пошукової бази знань після зміни або видалення інструкції"],"sources":[{"type":"vendor_documentation","url":"https://learn.microsoft.com/en-us/azure/search/search-how-to-index-azure-blob-changed-deleted","title":"Azure AI Search: Change and delete detection","checked_at":"2026-10-09","supports":"Change detection використовує timestamps, deletion потребує окремої політики від першого запуску. Для native soft delete потрібні сталі ключі й строк збереження довший за інтервал індексатора; reset не гарантує вилучення старих сирітських документів."},{"type":"inferred_pattern","title":"Редакційна модель міжкомандного та інформаційного контролю","supports":"Погодження, звірка, винятки, приклад, питання й години — гіпотези для аудиту. Первинні джерела описують власні системи постачальників, а не готову реалізацію PlanFix чи клієнтський кейс CRMCUSTOMS."}],"status":"draft","variants":[{"id":"knowledge-search-index-source-change-reconciliation-tracked","title":"Контроль із підтвердженням результату","description":"Змінені й вилучені джерела звіряють із фактично доступними пошуковими документами, щоб база не повертала застарілий зміст.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Вилучена інструкція все ще поверталась у пошуку. Команда звірила ключі фрагментів, погодила очищення й підтвердила відсутність старого результату.","implementation_methods":["Вести зв’язок джерела, редакції й пошукових фрагментів.","Звіряти актуальні та вилучені записи після завершення дозволеного індексування."],"complexity":"medium","hours_min":24,"hours_max":48,"requirements":["Є ключі джерел і фрагментів, редакції та доступний механізм оновлення індексу.","Визначено політику видалення, область й спосіб читання фактичного пошукового результату."],"limitations":["Не підтверджує правильність відповіді ШІ чи права доступу лише за успіхом індексування.","Виявлення видалень має окремі вимоги; пізнє додавання політики не гарантує очищення всіх старих сирітських записів."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0342","reason":"Версія навчального набору фіксує входи запуску моделі; тут актуальність індексу пошуку після змін джерел."},{"type":"related","target_id":"AUT-0150","reason":"Пошук факту перевіряє дозволену відповідь користувачу; тут джерело–індекс і фактичне оновлення або вилучення."},{"type":"related","target_id":"AUT-0082","reason":"Введення відповіді погоджує зміст статті, а не підтверджує її редакцію у похідному пошуковому індексі."},{"type":"related","target_id":"AUT-0432","reason":"Готовність звіту перевіряє вхідні дані періоду; тут вилучення й оновлення пошукових документів."}],"configurator_questions":[{"id":"knowledge-search-index-source-change-reconciliation-chunks","question":"Чи ділиться одне джерело на багато пошукових фрагментів?","help_text":"Збережіть зв’язки для повної звірки зміни й вилучення.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Збережіть зв’язки для повної звірки зміни й вилучення."}]},{"id":"knowledge-search-index-source-change-reconciliation-legacy","question":"Чи потрібно знайти старі сирітські записи без історії видалень?","help_text":"Погодьте повну область звірки та окреме рішення щодо перебудови.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":14,"add_hours_max":28,"assumption":"Погодьте повну область звірки та окреме рішення щодо перебудови."}]}]}];
